import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"WebAssembly Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"WebAssembly","tag":"WebAssembly","title":"WebAssembly Tag","prev":null,"next":null,"posts":[{"title":"编译 zbar 到 WebAssembly","url":"/posts/2024-06-01-zbar-wasm/","date":"2024-06-01 16:06","tags":["WebAssembly"],"html":"<p>工作上需要前端实现扫描二维码的功能，这部分属于图像识别的工作，图像识别相关的库基本都是 C 语言库，所以需要将这些库编译到 WebAssembly，然后在前端调用。</p>\\n<h2 id=\\"胶水函数\\" tabindex=\\"-1\\">胶水函数 <a class=\\"header-anchor\\" href=\\"#胶水函数\\" aria-label=\\"Permalink to &quot;胶水函数&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们需要将 C 语言的函数暴露出来，这样前端才能调用这些函数，这部分代码称为胶水函数。下面列举了一个简单的例子。</p>\\n<div class=\\"language-c line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">c</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;emscripten.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;zbar.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;stdio.h></span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#include</span><span style=\\"color:#032F62\\"> &#x3C;stdlib.h></span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">#define</span><span style=\\"color:#6F42C1\\"> EXPORT</span><span style=\\"color:#24292E\\"> EMSCRIPTEN_KEEPALIVE</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typedef</span><span style=\\"color:#D73A49\\"> int</span><span style=\\"color:#D73A49\\"> int32_t</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typedef</span><span style=\\"color:#D73A49\\"> unsigned</span><span style=\\"color:#D73A49\\"> int</span><span style=\\"color:#D73A49\\"> uint32_t</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EXPORT </span><span style=\\"color:#005CC5\\">zbar_image_scanner_t</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#6F42C1\\"> ImageScanner_create</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> zbar_image_scanner_create</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><h3 id=\\"编写-makefile\\" tabindex=\\"-1\\">编写 Makefile <a class=\\"header-anchor\\" href=\\"#编写-makefile\\" aria-label=\\"Permalink to &quot;编写 Makefile&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-makefile line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">makefile</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_VERSION = 0.23.90</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_SRC = zbar-</span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_VERSION</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">SRC = src</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">BUILD = build</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">DIST = dist</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EM_VERSION = 3.1.44</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># See https://emscripten.org/docs/tools_reference/emcc.html</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCC = emcc</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMMAKE = emmake</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCONFIG = emconfigure</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_DEPS = </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/make.done</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_OBJS = </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar/*.o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar/*/*.o</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">ZBAR_INC = -I </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/include/ -I </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># See https://github.com/emscripten-core/emscripten/blob/main/src/settings.js</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">EMCC_FLAGS = -Oz -Wall -Werror -s ALLOW_MEMORY_GROWTH=1 </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t-s EXPORTED_FUNCTIONS=\\"['_malloc','_free']\\" </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t-s MODULARIZE=1 -s EXPORT_NAME=zbarWasm</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">.PHONY</span><span style=\\"color:#24292E\\">: all build clean-build clean</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">all</span><span style=\\"color:#24292E\\">: build</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">build</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.wasm</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">clean-build</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm -rf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">DIST</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">clean</span><span style=\\"color:#24292E\\">: clean-build</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">\\t-</span><span style=\\"color:#24292E\\">rm -rf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.wasm </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/export.c</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tmkdir -p </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">\\t$(</span><span style=\\"color:#24292E\\">EMCC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">EMCC_FLAGS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> -o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">BUILD</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/zbar.js -sEXPORT_ES6 </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/export.c </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_INC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#032F62\\"> $(</span><span style=\\"color:#24292E\\">ZBAR_OBJS</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/Makefile</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcd </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> &#x26;&#x26; </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">EMMAKE</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> make CFLAGS=-Os CXXFLAGS=-Os </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\tDEFS=\\"-DZNO_MESSAGES -DHAVE_CONFIG_H\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttouch -m </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_DEPS</span><span style=\\"color:#032F62\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/Makefile: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcd </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> &#x26;&#x26; </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">EMCONFIG</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\"> ./configure --without-x --without-xshm </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-xv --without-jpeg --without-libiconv-prefix </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-imagemagick --without-npapi --without-gtk </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--without-python --without-qt --without-xshm --disable-video </span><span style=\\"color:#005CC5\\">\\\\</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\t\\t--disable-pthread --disable-assert --host=x86_64-linux-gnu</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure: </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttar zxvf </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\ttouch -m </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">/configure</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">\\tcurl -L -o </span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_SRC</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz https://linuxtv.org/downloads/zbar/zbar-</span><span style=\\"color:#032F62\\">$(</span><span style=\\"color:#24292E\\">ZBAR_VERSION</span><span style=\\"color:#032F62\\">)</span><span style=\\"color:#24292E\\">.tar.gz</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br></div></div><p>Makefile 中定义了编译 zbar 的流程，我们首先使用 curl 下载 zbar 的源码，然后解压，然后配置编译参数，最后编译生成 zbar 的调用 JS 和 WASM 文件。注意在配置参数中我们禁用了一些功能，因为这些功能在 WebAssembly 中不需要，并且在指定 host 的时候需要根据运行环境设置正确的参数，如果是运行在 Github Actions 中，需要设置为 <code>x86_64-linux-gnu</code>。如果是 M1 芯片的 Mac，需要设置为 <code>arm</code>。</p>\\n<h3 id=\\"函数封装\\" tabindex=\\"-1\\">函数封装 <a class=\\"header-anchor\\" href=\\"#函数封装\\" aria-label=\\"Permalink to &quot;函数封装&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>虽然我们从 zbar 暴露出来关键的图像处理相关的函数，但是用起来还不是那么方便，所以我们需要写一点 Typescript 的代码来封装这些函数。然后使用 rollup 打包成 JS 文件，并生成对应的 TS 类型文件。这部分实现细节就不赘述了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>编译 zbar 到 WebAssembly 的过程并不复杂，但是需要注意一些细节，比如编译参数的设置，胶水函数的编写等。这部分工作需要一定的 C 语言基础，如果没有的话，可以参考一些现成的例子，然后根据自己的需求进行修改。我也是参考网上的例子，然后根据自己的需求进行修改的。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/undecaf/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">undecaf/zbar-wasm</a></p>\\n<p><a href=\\"https://github.com/acgotaku/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">acgotaku/zbar-wasm</a></p>\\n"},{"title":"使用WebAssembly编译C++到JS","url":"/posts/2019-04-28-webassmebly/","date":"2019-04-28 20:51","tags":["WebAssembly"],"html":"<p>实际项目开发中遇到了一些已经使用 C++ 实现的功能，需要在新的 Web 客户端使用。由于主要是数学和算法的计算，没有平台依赖性。所以需要一个成本最低的移植方式，显然 WebAssembly 是一个非常好的方式。现在官方的编译工具是<a href=\\"https://github.com/emscripten-core/emscripten\\" target=\\"_blank\\" rel=\\"noreferrer\\">emscripten</a></p>\\n<h2 id=\\"移植方式\\" tabindex=\\"-1\\">移植方式 <a class=\\"header-anchor\\" href=\\"#移植方式\\" aria-label=\\"Permalink to &quot;移植方式&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>从 C++ 编译到 JS。官方提供了两种编译方式<a href=\\"https://emscripten.org/docs/porting/connecting_cpp_and_javascript/embind.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">embind</a>和<a href=\\"https://emscripten.org/docs/porting/connecting_cpp_and_javascript/WebIDL-Binder.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">WebIDL Binder</a>。这两种方式，一开始我也很困惑。不过现在也是有所了解了。向大家介绍一下如何选择。如果你的 C++ 项目中有很多高级数据结构要使用，例如 vector，map。那推荐使用 embind，如果你的项目主要是简单数据类型，例如数字，字符串，bool，都可以简单的映射到 JS，并且是用 class 封装的，那推荐使用 WebIDL Binder。</p>\\n<h2 id=\\"封装处理\\" tabindex=\\"-1\\">封装处理 <a class=\\"header-anchor\\" href=\\"#封装处理\\" aria-label=\\"Permalink to &quot;封装处理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>由于 C++ 数据结构比 JS 复杂的多，很多时候没有直接暴露成 JS 函数。我们需要进行封装，例如 C++ 中的引用调用，可以改变传入的参数的值。但是编译成 JS 的话，就不会生效。所以这时候我们需要写 wrap 函数，封装这些引用调用的 C++ 函数，然后再单独写 get 函数，得到修改的值。</p>\\n<h2 id=\\"webpack-打包\\" tabindex=\\"-1\\">webpack 打包 <a class=\\"header-anchor\\" href=\\"#webpack-打包\\" aria-label=\\"Permalink to &quot;webpack 打包&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>官方的 demo 是使用 src 的方式来引入，并且暴露成 <code>Module</code> 的全局变量。但是现代化的 Web 项目都是使用 webpack 打包，并且自动化引入的。所以我们也不想为了 WebAssembly 搞特殊。接下来就讲述如何配置来引入。首先，使用 emscripten 输出 <code>mjs</code> 文件，这样才可以作为模块被导入。具体的编译参数可以参照<a href=\\"https://emscripten.org/docs/tools_reference/emcc.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">emcc</a>。\\n首先，wasm 格式并不能被 webpack 正确识别，我们需要添加 loader</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  test</span><span style=\\"color:#24292E\\">:</span><span style=\\"color:#032F62\\"> /</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\.</span><span style=\\"color:#032F62\\">wasm</span><span style=\\"color:#D73A49\\">$</span><span style=\\"color:#032F62\\">/</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  type</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">'javascript/auto'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  loader</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">'file-loader'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>然后在项目中，分别 import mjs 文件和 wasm 文件。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> lib </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> './wasm.mjs'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> libWasm </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> './wasm.wasm'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> module</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> lib</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  locateFile</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">path</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (path.</span><span style=\\"color:#6F42C1\\">endsWith</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'.wasm'</span><span style=\\"color:#24292E\\">)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      return</span><span style=\\"color:#24292E\\"> libWasm;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> path;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>然后在调用的时候替换掉默认的<code>locateFile</code>函数，即可完美导入到我们的项目中。</p>\\n<h2 id=\\"内存泄漏\\" tabindex=\\"-1\\">内存泄漏 <a class=\\"header-anchor\\" href=\\"#内存泄漏\\" aria-label=\\"Permalink to &quot;内存泄漏&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>C++ 中有很多高级的数据结构，我们可以映射成 JS 对象，但是内存管理还是需要自己处理。所有我们声明的 WebAssembly 数据结构并且包括函数返回的数据结构，都需要手动调用 <code>delete</code> 方法来释放内存。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>编译 C++ 到 JS，不仅需要 JS 的知识，还需要 C++ 知识，我们需要先把所有需要的 C++ 文件，先全部编译到 LLVM bitcode（.o 文件）。这里编译 C++ 可以使用 GCC 的全部编译参数，推荐使用 O3 参数来优化代码。最后编译到 JS 文件的时候，需要按照 emscripten 的规范来书写胶水文件。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://gist.github.com/surma/b2705b6cca29357ebea1c9e6e15684cc\\" target=\\"_blank\\" rel=\\"noreferrer\\">webpack-emscripten-wasm</a></p>\\n"}]},"relativePath":"tags/WebAssembly/index.md","filePath":"tags/[slug].md"}`),l={name:"tags/WebAssembly/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const m=s(l,[["render",p]]);export{y as __pageData,m as default};
